local MainspringWinderMaker = {}
local PRODUCTS = {
    iron_mainspringwinder = { name = "Železni navijalec vzmeti", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni navijalec vzmeti za ure." },
    bronze_mainspringwinder = { name = "Bronast navijalec vzmeti", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast navijalec vzmeti za ure." },
    silver_mainspringwinder = { name = "Srebrn navijalec vzmeti", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn navijalec vzmeti za ure." },
    gilded_mainspringwinder = { name = "Pozlačen navijalec vzmeti", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen navijalec vzmeti za ure." },
    jewel_set_mainspringwinder = { name = "Draguljast navijalec vzmeti", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast navijalec vzmeti za ure." },
    royal_sovereign_mainspringwinder = { name = "Kraljevski suveren navijalec vzmeti", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren navijalec vzmeti z biseri za krono." },
}
local BUILDINGS = {
    mainspringwinder_workshop = { name = "Mainspringwinder delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    mainspringwinder_house = { name = "Mainspringwinder hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_mainspringwinder_atelier = { name = "Mojstrski mainspringwinder atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_mainspringwinder_palace = { name = "Suverena mainspringwinder palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MainspringWinderMaker.ironStock = 16; MainspringWinderMaker.bronzeStock = 14; MainspringWinderMaker.woodStock = 12; MainspringWinderMaker.leatherStock = 8; MainspringWinderMaker.silverStock = 8; MainspringWinderMaker.goldStock = 6; MainspringWinderMaker.jewelStock = 4; MainspringWinderMaker.pearlStock = 4
MainspringWinderMaker.productStock = {}; MainspringWinderMaker.buildings = {}; MainspringWinderMaker.maker = nil; MainspringWinderMaker.activeMaking = {}; MainspringWinderMaker.totalProducts = 0; MainspringWinderMaker.dayTimer = 0
function MainspringWinderMaker.init() MainspringWinderMaker.ironStock=16; MainspringWinderMaker.bronzeStock=14; MainspringWinderMaker.woodStock=12; MainspringWinderMaker.leatherStock=8; MainspringWinderMaker.silverStock=8; MainspringWinderMaker.goldStock=6; MainspringWinderMaker.jewelStock=4; MainspringWinderMaker.pearlStock=4; MainspringWinderMaker.productStock={}; MainspringWinderMaker.buildings={}; MainspringWinderMaker.maker=nil; MainspringWinderMaker.activeMaking={}; MainspringWinderMaker.totalProducts=0; MainspringWinderMaker.dayTimer=0; print("[MainspringWinderMaker] Royal Mainspring Winder Maker System initialized (6 products, 4 buildings)") end
function MainspringWinderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MainspringWinderMaker.maker={name=n or ("Vzmetar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzmetar najet: %s (spretnost: %d)",MainspringWinderMaker.maker.name,s),"success") end; return true end
function MainspringWinderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MainspringWinderMaker.build(id) local ok,e=MainspringWinderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MainspringWinderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MainspringWinderMaker.getQualityBonus() local b=0; for _,bd in ipairs(MainspringWinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MainspringWinderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MainspringWinderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MainspringWinderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MainspringWinderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MainspringWinderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MainspringWinderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MainspringWinderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MainspringWinderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MainspringWinderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MainspringWinderMaker.buildings==0 then return false,"Potrebna vzmetna delavnica" end; if not MainspringWinderMaker.maker then return false,"Potreben vzmetar" end; return true end
function MainspringWinderMaker.make(pt,qty) qty=qty or 1; local ok,e=MainspringWinderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MainspringWinderMaker.ironStock=MainspringWinderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MainspringWinderMaker.bronzeStock=MainspringWinderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MainspringWinderMaker.woodStock=MainspringWinderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MainspringWinderMaker.leatherStock=MainspringWinderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MainspringWinderMaker.silverStock=MainspringWinderMaker.silverStock-d.silverCost*qty end; if d.goldCost then MainspringWinderMaker.goldStock=MainspringWinderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MainspringWinderMaker.jewelStock=MainspringWinderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MainspringWinderMaker.pearlStock=MainspringWinderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MainspringWinderMaker.maker then t=math.max(1,t-math.floor(MainspringWinderMaker.maker.skill/13)) end; table.insert(MainspringWinderMaker.activeMaking,{id="mainspringwinder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MainspringWinderMaker.completeMaking(m) local q=1.0+(MainspringWinderMaker.getQualityBonus()/100); if MainspringWinderMaker.maker then q=q+(MainspringWinderMaker.maker.skill/140) end; q=math.min(2.5,q); MainspringWinderMaker.productStock[m.productType]=(MainspringWinderMaker.productStock[m.productType] or 0)+m.quantity; MainspringWinderMaker.totalProducts=MainspringWinderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MainspringWinderMaker.maker then MainspringWinderMaker.maker.itemsMade=MainspringWinderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MainspringWinderMaker.maker.skill=math.min(100,MainspringWinderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mainspringwinder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MainspringWinderMaker.update(dt) if not _G.state then return end; MainspringWinderMaker.dayTimer=MainspringWinderMaker.dayTimer+dt; if MainspringWinderMaker.dayTimer>=30 then MainspringWinderMaker.dayTimer=0; for i=#MainspringWinderMaker.activeMaking,1,-1 do local m=MainspringWinderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MainspringWinderMaker.completeMaking(m); table.remove(MainspringWinderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MainspringWinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MainspringWinderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MainspringWinderMaker.getStats() return {ironStock=MainspringWinderMaker.ironStock,bronzeStock=MainspringWinderMaker.bronzeStock,woodStock=MainspringWinderMaker.woodStock,leatherStock=MainspringWinderMaker.leatherStock,silverStock=MainspringWinderMaker.silverStock,goldStock=MainspringWinderMaker.goldStock,jewelStock=MainspringWinderMaker.jewelStock,pearlStock=MainspringWinderMaker.pearlStock,productStock=MainspringWinderMaker.productStock,numBuildings=#MainspringWinderMaker.buildings,hasMaker=MainspringWinderMaker.maker~=nil,makerName=MainspringWinderMaker.maker and MainspringWinderMaker.maker.name or "—",makerSkill=MainspringWinderMaker.maker and MainspringWinderMaker.maker.skill or 0,activeMaking=#MainspringWinderMaker.activeMaking,totalProducts=MainspringWinderMaker.totalProducts} end
return MainspringWinderMaker
